"""Convert pip's resolved installation report into a target-specific artifact lock."""
import argparse
import hashlib
import json
import re
from pathlib import Path


def render_lock(report, requirements):
    environment = report["environment"]
    if (environment["python_full_version"] != "3.14.5" or
            environment["sys_platform"] != "win32" or
            environment["platform_machine"].lower() != "amd64"):
        raise ValueError("This lock targets CPython 3.14.5 on Windows AMD64 only")
    lines = [
        "# Generated by python -m scripts.lock_dependencies; do not edit.",
        "# Target: CPython 3.14.5 / Windows AMD64; pip resolver 26.1.1.",
        f"# requirements.in sha256: {hashlib.sha256(requirements).hexdigest()}",
        "# All direct and transitive dependencies, with selected wheel hashes.",
        "--only-binary=:all:", ""
    ]
    entries = {}
    for item in report["install"]:
        metadata, download = item["metadata"], item["download_info"]
        name = re.sub(r"[-_.]+", "-", metadata["name"]).lower()
        version = metadata["version"]
        digest = download["archive_info"]["hashes"]["sha256"]
        if not download["url"].split("?")[0].endswith(".whl"):
            raise ValueError("Only resolved wheels may be locked")
        if not re.fullmatch(r"[a-z0-9-]+", name) or not re.fullmatch(r"[0-9A-Za-z.+!-]+", version):
            raise ValueError("Invalid dependency identity")
        if not re.fullmatch(r"[0-9a-f]{64}", digest) or name in entries:
            raise ValueError("Invalid hash or duplicate dependency")
        entries[name] = f"{name}=={version} --hash=sha256:{digest}"
    direct = [line.strip() for line in requirements.decode("utf-8-sig").splitlines()
              if line.strip() and not line.startswith("#")]
    for requirement in direct:
        name, version = requirement.split("==")
        name = re.sub(r"[-_.]+", "-", name).lower()
        if not entries.get(name, "").startswith(f"{name}=={version} "):
            raise ValueError(f"Direct dependency missing from report: {name}")
    return "\n".join(lines + [entries[name] for name in sorted(entries)]) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--report", type=Path, default=Path("data/dependency-resolution.json"))
    parser.add_argument("--output", type=Path, default=Path("requirements.txt"))
    args = parser.parse_args()
    report = json.loads(args.report.read_text(encoding="utf-8"))
    if report.get("pip_version") != "26.1.1":
        raise ValueError("Regenerate with pip 26.1.1")
    lock = render_lock(report, Path("requirements.in").read_bytes())
    args.output.write_text(lock, encoding="utf-8", newline="\n")
    print(f"Locked {len(report['install'])} packages for Windows AMD64 / CPython 3.14.5")


if __name__ == "__main__":
    main()
